    elif model_type == 'ridge':
        return ridge_model.predict(features.reshape(-1, 1))[0]
    elif model_type == 'random_forest' or model_type == 'best_model':
        return rf_model.predict(features.reshape(-1, 1))[0]
    else:
        raise ValueError(f"Unknown model type: {model_type}")

# Endpoint 1: POST /predict
