    """Predict house price using trained models"""
    try:
        # Parse features from JSON
        features = features_data.get("features", [])

        # Validate features has exactly 8 elements
        if not isinstance(features, list) or len(features) != 8:
            raise HTTPException(status_code=400, detail="Features must be a list of 8 floats")

        # Convert to numpy array
        X = np.array([np.float64(f) for f in features])

        # Get model name from request (or use default)
        model_name = "random_forest"  # Default to best model

        # Make prediction
        prediction = predict_model(X, model_name)

        return {
            "prediction": float(prediction),
            "model_name": model_name
        }
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

# Endpoint 2: GET /health
@app.get("/health")
def health_check():
    """Health check endpoint"""
    return {
        "status": "healthy",
        "model_loaded": True
    }

# Endpoint 3: GET /model-info
@app.get("/model-info")
def get_model_info():
    """Get information about trained models"""
    return {
        "model_name": "random_forest",
        "model_type": "RandomForestRegressor",
        "features_count": 8
    }

# Endpoint 4: POST /predict-batch
# Input: {"features_list": [[float,...], [float,...], ...]}
# Each inner array has exactly 8 features
@app.post("/predict-batch", response_model=None)
def predict_batch(features_list):
    """Batch prediction for multiple samples"""
    try:
        # Parse features_list from JSON
        features_list = features_list.get("features_list", [])

        # Validate each sample has exactly 8 features
        predictions = []
        model_name = "random_forest"

        for i, features in enumerate(features_list):
            if not isinstance(features, list) or len(features) != 8:
                raise HTTPException(status_code=400, detail=f"Sample {i} must have exactly 8 features")

            # Convert to numpy array
            X_sample = np.array([np.float64(f) for f in features])

            # Make prediction
            prediction = predict_model(X_sample, model_name)
            predictions.append(float(prediction))

        return {
            "predictions": predictions,
            "model_name": model_name,
            "count": len(predictions)
        }
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

# Startup event to ensure models are loaded
@app.on_event("startup")
def startup_event():
    """Ensure models are loaded on application start"""
    pass

if __name__ == "__main__":
    import uvicorn
    # Start server
    uvicorn.run(app, host="0.0.0.0", port=8000)
