# Endpoint 4: POST /predict-batch
# Input schema:
# {
#   "features_list": [
#     [float, float, float, float, float, float, float, float],
#     [float, float, float, float, float, float, float, float],
#     ...
#   ]
# }
# Each inner array must have exactly 8 features
@app.post("/predict-batch", response_model=None)
def predict_batch(request: BatchPredictionRequest):
    """Batch prediction for multiple samples"""
    try:
        # Validate each sample has exactly 8 features
        predictions = []
        model_name = "random_forest"

        for features in request.features_list:
            if not isinstance(features, list) or len(features) != 8:
                raise HTTPException(status_code=400, detail=f"Sample must have exactly 8 features")

            # Convert to numpy array
            X_sample = np.array([np.float64(f) for f in features])

            # Make prediction using loaded model
            prediction = predict_model(X_sample, model_name)
            predictions.append(float(prediction))

        return {
            "predictions": predictions,
            "model_name": model_name,
            "count": len(predictions)
        }
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

